import React, { useState, useEffect } from "react";
import Swal from "sweetalert2";
import "bootstrap/dist/css/bootstrap.min.css";
import config from "./config";

const App = () => {
  const [nombre, setNombre] = useState("");
  const [imagen, setImagen] = useState("");
  const [preview, setPreview] = useState(null);
  const [usuarioCreacion, setUsuarioCreacion] = useState("");

  const getUrlParams = () => {
    const params = new URLSearchParams(window.location.search);
    const id = params.get("id");

    if (!id) {
      throw new Error("Falta el parámetro ID en la URL.");
    }

    return { id };
  };

  const handleTokenError = () => {
    localStorage.removeItem("token");
    Swal.fire("Error", "No estás autenticado. Por favor, inicia sesión.", "error").then(() => {
      window.location.href = "/";
    });
  };

  const decrypt = async (value) => {
    if (!value || value.trim() === "") {
      throw new Error("El valor encriptado está vacío o es inválido.");
    }

    const token = localStorage.getItem("token");
    if (!token) {
      handleTokenError();
      return;
    }

    const response = await fetch(`${config.API_BASE_URL}/decrypt`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ encrypted_value: value }),
    });

    if (response.status === 401) {
      handleTokenError();
      return;
    }

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Error al desencriptar: ${errorText}`);
    }

    const data = await response.json();
    if (!data.decrypted_value) {
      throw new Error("La API no devolvió un valor desencriptado.");
    }

    return data.decrypted_value;
  };

  useEffect(() => {
    const initializeUsuarioCreacion = async () => {
      try {
        const urlParams = getUrlParams();
        const decryptedId = await decrypt(urlParams.id);
        setUsuarioCreacion(decryptedId);
      } catch (error) {
        Swal.fire("Error", `No se pudo inicializar el usuario: ${error.message}`, "error");
      }
    };

    initializeUsuarioCreacion();
  }, []);

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        setImagen(reader.result.split(",")[1]); // Guardar en Base64 (sin encabezado)
        setPreview(reader.result); // Mostrar imagen en el previsualizador
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async () => {
    try {
      if (!nombre || !imagen || !usuarioCreacion) {
        throw new Error("Todos los campos son obligatorios.");
      }

      const token = localStorage.getItem("token");
      if (!token) {
        handleTokenError();
        return;
      }

      const response = await fetch(`${config.API_BASE_URL}/modulos/insert`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          nombre,
          imagen,
          usuario_creacion: usuarioCreacion,
        }),
      });

      if (!response.ok) {
        throw new Error(`Error al guardar el módulo: ${response.statusText}`);
      }

      Swal.fire("Éxito", "El módulo se guardó correctamente.", "success");
    } catch (error) {
      Swal.fire("Error", `No se pudo guardar el módulo: ${error.message}`, "error");
    }
  };

  return (
    <div className="container mt-5">
      <div className="card">
        <div className="card-header text-center">
          <h4>Registrar Módulo</h4>
        </div>
        <div className="card-body">
          <div className="mb-3">
            <label htmlFor="nombre" className="form-label">
              Nombre del módulo:
            </label>
            <input
              type="text"
              id="nombre"
              className="form-control"
              value={nombre}
              onChange={(e) => setNombre(e.target.value)}
            />
          </div>
          <div className="mb-3">
            <label htmlFor="imagen" className="form-label">
              Cargar imagen:
            </label>
            <input
              type="file"
              id="imagen"
              className="form-control"
              accept="image/*"
              onChange={handleImageUpload}
            />
          </div>
          {preview && (
            <div className="mb-3">
              <label className="form-label">Vista previa:</label>
              <img src={preview} alt="Previsualización" className="img-thumbnail" />
            </div>
          )}
          <button className="btn btn-primary" onClick={handleSubmit}>
            Guardar Módulo
          </button>
        </div>
      </div>
    </div>
  );
};

export default App;
